def cache_sim(capacity, ttl, ops):
    store = {}  # key -> (value, expire_time)
    results = []

    def purge_expired(current_t):
        expired_keys = [k for k, (v, exp) in store.items() if current_t >= exp]
        for k in expired_keys:
            del store[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'get':
            key = op[2]
            if key in store:
                value, expire = store[key]
                if t >= expire:
                    del store[key]
                    results.append(-1)
                else:
                    # move to end (most recently used)
                    del store[key]
                    store[key] = (value, expire)
                    results.append(value)
            else:
                results.append(-1)
        elif kind == 'put':
            key = op[2]
            value = op[3]
            existing_present = False
            if key in store:
                old_value, expire = store[key]
                if t < expire:
                    existing_present = True
                else:
                    # expired, remove it
                    del store[key]

            if existing_present:
                # update value, refresh expiry, move to end
                del store[key]
                store[key] = (value, t + ttl)
            else:
                # purge all expired entries before checking capacity
                purge_expired(t)
                if key in store:
                    del store[key]
                if len(store) >= capacity:
                    # evict least recently used (first item in dict order)
                    lru_key = next(iter(store))
                    del store[lru_key]
                store[key] = (value, t + ttl)

    return results

